fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Initialize a result vector with the same length as the input arrays
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through both arrays and compare their elements
    for (x, y) in a.iter().zip(b.iter()) {
        // Convert i8 to i32 and compare
        result.push((*x as i32) > (*y as i32));
    }
    
    result
}